29	// updateTableData refreshes table rows from entries, applying active filters
30	func (m *Model) updateTableData() {
31		query := strings.ToLower(m.filterBar.SearchQuery())
32	
33		rows := make([]table.Row, 0, len(m.entries))
34		for _, entry := range m.entries {
35			// Apply text search filter
36			if query != "" {
37				nameMatch := strings.Contains(strings.ToLower(entry.Name), query)
38				remoteMatch := strings.Contains(strings.ToLower(entry.GitRemote), query)
39				if !nameMatch && !remoteMatch {
40					continue
41				}
42			}
43	
44			typeIcon := formatProjectType(entry)
45			// if typeWidth > 0 && typeIcon != "" {
46			// 	typeIcon = theme.CenterInColumn(typeIcon, typeWidth)
47			// }
48			sensitive, c, h, med, l, scanned := m.formatScanColumns(entry)
49			rows = append(rows, table.Row{
50				entry.Name,
51				entry.GitRemote,
52				formatGitStatus(entry),
53				typeIcon,
54				sensitive,
55				c,
56				h,
57				med,
58				l,
59				scanned,
60				timeAgo(entry.ModTime),
61			})
62		}
63		m.table.SetRows(rows)
64	
65		// bubbles does not clamp the cursor when the row count shrinks, so drilling
66		// into a smaller directory — or narrowing the filter — would leave it past
67		// the end. Nothing is highlighted then, and every action that resolves the
68		// selection (enter, ctrl+d, r, ctrl+s) silently does nothing.
69		if m.table.Cursor() >= len(rows) {
70			m.table.SetCursor(max(len(rows)-1, 0))
71		}
72	}
