74	// loadEntries loads the contents of the current directory with enriched metadata
75	func (m Model) loadEntries() tea.Cmd {
76		currentPath := m.currentPath
77		workspacesDir := m.getExpandedWorkspacesDir()
78	
79		return func() tea.Msg {
80			targetDir := workspacesDir
81			if currentPath != "" {
82				targetDir = currentPath
83			}
84	
85			// Check if directory exists, create it if it doesn't (only for workspaces root)
86			if _, err := os.Stat(targetDir); os.IsNotExist(err) {
87				if currentPath == "" {
88					if err := os.MkdirAll(targetDir, 0755); err != nil {
89						return LoadErrorMsg{Error: err}
90					}
91					return EntriesLoadedMsg{Entries: []Entry{}}
92				}
93				return LoadErrorMsg{Error: err}
94			}
95	
96			dirEntries, err := os.ReadDir(targetDir)
97			if err != nil {
98				return LoadErrorMsg{Error: err}
99			}
100	
101			entries := make([]Entry, 0, len(dirEntries))
102			for _, dirEntry := range dirEntries {
103				// Skip hidden files/directories
104				if strings.HasPrefix(dirEntry.Name(), ".") {
105					continue
106				}
107	
108				info, err := dirEntry.Info()
109				if err != nil {
110					continue
111				}
112	
113				entry := Entry{
114					Name:    dirEntry.Name(),
115					Path:    filepath.Join(targetDir, dirEntry.Name()),
116					ModTime: info.ModTime(),
117					IsDir:   dirEntry.IsDir(),
118				}
119	
120				// Enrich directory entries with git and project type info
121				if entry.IsDir {
122					enrichEntry(&entry)
123				}
124	
125				entries = append(entries, entry)
126			}
127	
128			return EntriesLoadedMsg{Entries: entries}
129		}
130	}
