33	// In resize: tableHeight := height - fb.ExtraHeight()
34	// In view:   append fb.View() as the last line after the table
35	// In update: forward keys to fb.Update(msg) when fb.InEditMode()
36	type FilterBar struct {
37		searching   bool
38		searchInput textinput.Model
39		searchQuery string
40		tokens      []FilterToken
41		width       int
42	}
