54	func newFilterBar(tokens []FilterToken) FilterBar {
55		si := textinput.New()
56		theme.StyleTextInput(&si)
57		si.CharLimit = 100
58	
59		fb := FilterBar{
60			searchInput: si,
61		}
62		if len(tokens) > 0 {
